def ddl():
    parts=['-- Target design only. Never run against the existing SQLite or pilot database.',
      '-- Proposed physical names/UUID/precision/RLS are project decisions. Teacher sources govern behavior.',
      'BEGIN;','CREATE SCHEMA cp_target;',
      'CREATE TABLE cp_target.organizations (org_id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());']
    # Define all tables before adding cross-table foreign keys.
    for t in TABLES:
        cols=['id uuid PRIMARY KEY DEFAULT gen_random_uuid()', 'org_id uuid NOT NULL REFERENCES cp_target.organizations(org_id)', 'created_at timestamptz NOT NULL DEFAULT now()', 'updated_at timestamptz NOT NULL DEFAULT now()', 'version integer NOT NULL DEFAULT 1 CHECK (version > 0)']
        cols += [f'{k} {v}' for k,v in t['fields'].items()]
        cols += ['UNIQUE (org_id, id)']
        cols += ['UNIQUE ('+', '.join(('org_id',)+u)+')' for u in t['unique']]
        cols += ['CHECK ('+s+')' for s in t['checks']]
        parts += [f"CREATE TABLE cp_target.{t['name']} (\n  "+',\n  '.join(cols)+'\n);',f"CREATE INDEX {t['name']}_tenant_time ON cp_target.{t['name']} (org_id, created_at DESC);"]
    for t in TABLES:
        for col,target in t['refs']:
            parts += [f"ALTER TABLE cp_target.{t['name']} ADD FOREIGN KEY (org_id, {col}) REFERENCES cp_target.{target} (org_id, id);"]
        n=t['name']
        parts += [f'ALTER TABLE cp_target.{n} ENABLE ROW LEVEL SECURITY;',f'ALTER TABLE cp_target.{n} FORCE ROW LEVEL SECURITY;',f"CREATE POLICY tenant_scope ON cp_target.{n} USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);"]
    parts += ["CREATE UNIQUE INDEX one_selected_asset ON cp_target.generation_assets (org_id, job_id) WHERE selected AND deleted_at IS NULL;",'COMMIT;']
    return '\n\n'.join(parts)+'\n'
(TARGET/'target-schema.sql').write_text(ddl(),encoding='utf-8')
(TARGET/'table-catalog.json').write_text(json.dumps(TABLES,ensure_ascii=False,indent=2),encoding='utf-8')
print('Target tables:',len(TABLES))
